package com.example.masroofy;

import java.time.LocalDate;
import java.util.*;
import java.time.LocalDateTime;

public class AppManager {

    private static final int NO_USER_ID = -1;

    private int currentUserId;
    private  UserDAO userDAO;
    private  CycleDAO cycleDAO;
    private  ExpenseDAO expenseDAO;
    private  AuthDAO authDAO;
    private  AUTH auth;
    private  CategoryDAO categoryDAO;
    private  DataBaseManager dbManager;

    public AppManager(DataBaseManager dbManager) {
        this.currentUserId = NO_USER_ID;
        this.dbManager = dbManager;
        this.userDAO = new UserDAO(dbManager);
        this.cycleDAO = new CycleDAO(dbManager);
        this.expenseDAO = new ExpenseDAO(dbManager);
        this.authDAO = new AuthDAO(dbManager);
        this.categoryDAO = new CategoryDAO(dbManager);
        this.auth = new AUTH();
    }

    // ── AUTH ──────────────────────────────────

    public int registerUser(String pin ,String name) {
        if (name == null || name.isBlank()) {
            return NO_USER_ID;
        }

        if (!auth.isValidpin(pin)) {
            return NO_USER_ID;
        }

        currentUserId = userDAO.createUser(name.trim());
        authDAO.savePin(currentUserId, pin);
        return currentUserId;
    }

    public boolean login(int userId, String pin) {
        String storedPin = authDAO.getPin(userId);
        if (storedPin != null && auth.verfiypin(storedPin, pin)) {
            currentUserId = userId;
            return true;
        }
        return false;
    }

    public void logout() {
        currentUserId = -1;
    }

    public boolean changePin(String Input ,String newPin) {
       String oldPin = authDAO.getPin(currentUserId);
       if(auth.changepin(oldPin,Input,newPin)){
           return authDAO.updatePin(currentUserId, newPin);
       }
       else{
           return false;
       }
    }

    // ── CYCLE ─────────────────────────────────

    public void setupCycle(double totalBudget, LocalDate startDate, LocalDate endDate) {
        cycleDAO.setupCycle(new Cycle(currentUserId, totalBudget, startDate, endDate));
    }

    public void resetCycle() {
        cycleDAO.resetCycle(currentUserId);
    }

    public Cycle getCurrentCycle() {
        return cycleDAO.getCycleByUser(currentUserId);
    }

    // ── EXPENSES ──────────────────────────────

    public void addExpense(double amount, int categoryid , String TYPE) {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return;
        }
        expenseDAO.addExpense(new Expense(amount,TYPE,categoryid,LocalDateTime.now(),cycle.getId()));
    }

    public boolean editExpense(int id, double newAmount, int Categoryid) {
        return expenseDAO.updateExpense(new Expense(id,newAmount,Categoryid));
    }

    public boolean deleteExpense(int id) {
        return expenseDAO.deleteExpense(id);
    }

    public List<Expense> getAllExpenses() {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return new ArrayList<>();
        }
        return expenseDAO.getAllExpenses(cycle.getId());
    }

    // ── CATEGORIES ────────────────────────────

    public void addCategory(String name) {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null || name == null || name.isBlank()) {
            return;
        }
        if (!categoryDAO.categoryExists(cycle.getId(), name)) {
            categoryDAO.addCategory(cycle.getId(), name);
        }
    }

    public List<String> getCategories() {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return new ArrayList<>();
        }

        List<Category> categories = categoryDAO.getAllCategories(cycle.getId());

        List<String> names = new ArrayList<>();

        for (Category c : categories) {
            names.add(c.getName());
        }

        return names;
    }

    public boolean deleteCategory(String name) {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null || name == null) {
            return false;
        }

        List<Category> categories = categoryDAO.getAllCategories(cycle.getId());
        for (Category category : categories) {
            if (category.getName().equals(name)) {
                return categoryDAO.deleteCategory(category.getId());
            }
        }

        return false;
    }

    // ── INCOME ────────────────────────────────

    public void addIncome(double amount) {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return;
        }
        cycleDAO.addToBudget(cycle.getId(), amount);
    }

    // ── STATS ─────────────────────────────────

    public double getTotalSpent() {

        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return 0.0;
        }

        return expenseDAO.getTotalByCycle(cycle.getId());
    }

    public double getRemainingBalance() {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return 0.0;
        }
        return cycle.getRemainigBalance(getTotalSpent());
    }

    public double getDailyLimit() {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return 0.0;
        }
        return cycle.calulatedailyBudget(getTotalSpent());
    }

    public Map<String, Double> getCategoryTotals() {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return new HashMap<>();
        }
        return expenseDAO.getCategoryTotals(cycle.getId());
    }

    public double getWeeklyTotalSpent() {

        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return 0.0;
        }

        LocalDate today = LocalDate.now();
        LocalDate weekStart = today.minusDays(today.getDayOfWeek().getValue() - 1);
        LocalDate weekEnd = weekStart.plusDays(6);

        return expenseDAO.getWeeklyTotal(cycle.getId(), weekStart, weekEnd);
    }

    public List<Expense> getYesterdayExpenses() {

        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return new ArrayList<>();
        }

        return expenseDAO.getExpensesByDate(cycle.getId(), LocalDate.now().minusDays(1));
    }

    public List<Expense> getTodayExpenses() {

        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return new ArrayList<>();
        }

        return expenseDAO.getExpensesByDate(cycle.getId(), LocalDate.now());
    }


    public int getUserId() {
        return currentUserId;
    }

    public boolean isLoggedIn() {
        return currentUserId != NO_USER_ID;
    }

    public String getCurrentUserName() {
        if (!isLoggedIn()) {
            return null;
        }
        User user = userDAO.getUserById(currentUserId);
        return user == null ? null : user.getUsername();
    }

    public int getCategoryIdByName(String name) {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null || name == null) {
            return -1;
        }

        List<Category> categories = categoryDAO.getAllCategories(cycle.getId());
        for (Category category : categories) {
            if (category.getName().equals(name)) {
                return category.getId();
            }
        }

        return -1;
    }

    public String getCategoryNameById(int id) {
        Category category = categoryDAO.getCategoryById(id);
        return category == null ? null : category.getName();
    }
}

package com.example.masroofy;

import java.time.LocalDate;
import java.util.*;
import java.time.LocalDateTime;

public class AppManager {

    private static final int NO_USER_ID = -1;

    private int currentUserId;
    private  UserDAO userDAO;
    private  CycleDAO cycleDAO;
    private  ExpenseDAO expenseDAO;
    private  AuthDAO authDAO;
    private  AUTH auth;
    private  CategoryDAO categoryDAO;
    private  DataBaseManager dbManager;

    public AppManager(DataBaseManager dbManager) {
        this.currentUserId = NO_USER_ID;
        this.dbManager = dbManager;
        this.userDAO = new UserDAO(dbManager);
        this.cycleDAO = new CycleDAO(dbManager);
        this.expenseDAO = new ExpenseDAO(dbManager);
        this.authDAO = new AuthDAO(dbManager);
        this.categoryDAO = new CategoryDAO(dbManager);
        this.auth = new AUTH();
    }

    // ── AUTH ──────────────────────────────────

    public int registerUser(String pin ,String name) {
        if (name == null || name.isBlank()) {
            return NO_USER_ID;
        }

        if (!auth.isValidpin(pin)) {
            return NO_USER_ID;
        }

        currentUserId = userDAO.createUser(name.trim());
        if (currentUserId == NO_USER_ID) {
            return NO_USER_ID;
        }
        authDAO.savePin(currentUserId, pin);
        return currentUserId;
    }

    public boolean login(int userId, String pin) {
        String storedPin = authDAO.getPin(userId);
        if (storedPin != null && auth.verfiypin(storedPin, pin)) {
            currentUserId = userId;
            return true;
        }
        return false;
    }

    public void logout() {
        currentUserId = -1;
    }

    public boolean changePin(String Input ,String newPin) {
       String oldPin = authDAO.getPin(currentUserId);
       if(auth.changepin(oldPin,Input,newPin)){
           return authDAO.updatePin(currentUserId, newPin);
       }
       else{
           return false;
       }
    }

    // ── CYCLE ─────────────────────────────────

    public void setupCycle(double totalBudget, LocalDate startDate, LocalDate endDate) {
        cycleDAO.setupCycle(new Cycle(currentUserId, totalBudget, startDate, endDate));
    }

    public void resetCycle() {
        cycleDAO.resetCycle(currentUserId);
    }

    public Cycle getCurrentCycle() {
        return cycleDAO.getCycleByUser(currentUserId);
    }

    // ── EXPENSES ──────────────────────────────

    public void addExpense(double amount, int categoryid , String TYPE) {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return;
        }
        expenseDAO.addExpense(new Expense(amount,TYPE,categoryid,LocalDateTime.now(),cycle.getId()));
    }

    public boolean editExpense(int id, double newAmount, int Categoryid) {
        return expenseDAO.updateExpense(new Expense(id,newAmount,Categoryid));
    }

    public boolean deleteExpense(int id) {
        return expenseDAO.deleteExpense(id);
    }

    public List<Expense> getAllExpenses() {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return new ArrayList<>();
        }
        return expenseDAO.getAllExpenses(cycle.getId());
    }

    // ── CATEGORIES ────────────────────────────

    public void addCategory(String name) {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null || name == null || name.isBlank()) {
            return;
        }
        if (!categoryDAO.categoryExists(cycle.getId(), name)) {
            categoryDAO.addCategory(cycle.getId(), name);
        }
    }

    public List<String> getCategories() {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return new ArrayList<>();
        }

        List<Category> categories = categoryDAO.getAllCategories(cycle.getId());

        List<String> names = new ArrayList<>();

        for (Category c : categories) {
            names.add(c.getName());
        }

        return names;
    }

    public boolean deleteCategory(String name) {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null || name == null) {
            return false;
        }

        List<Category> categories = categoryDAO.getAllCategories(cycle.getId());
        for (Category category : categories) {
            if (category.getName().equals(name)) {
                return categoryDAO.deleteCategory(category.getId());
            }
        }

        return false;
    }

    // ── INCOME ────────────────────────────────

    public void addIncome(double amount) {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return;
        }
        cycleDAO.addToBudget(cycle.getId(), amount);
    }

    // ── STATS ─────────────────────────────────

    public double getTotalSpent() {

        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return 0.0;
        }

        return expenseDAO.getTotalByCycle(cycle.getId());
    }

    public double getRemainingBalance() {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return 0.0;
        }
        return cycle.getRemainigBalance(getTotalSpent());
    }

    public double getDailyLimit() {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return 0.0;
        }
        return cycle.calulatedailyBudget(getTotalSpent());
    }

    public Map<String, Double> getCategoryTotals() {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return new HashMap<>();
        }
        return expenseDAO.getCategoryTotals(cycle.getId());
    }

    public double getWeeklyTotalSpent() {

        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return 0.0;
        }

        LocalDate today = LocalDate.now();
        LocalDate weekStart = today.minusDays(today.getDayOfWeek().getValue() - 1);
        LocalDate weekEnd = weekStart.plusDays(6);

        return expenseDAO.getWeeklyTotal(cycle.getId(), weekStart, weekEnd);
    }

    public List<Expense> getYesterdayExpenses() {

        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return new ArrayList<>();
        }

        return expenseDAO.getExpensesByDate(cycle.getId(), LocalDate.now().minusDays(1));
    }

    public List<Expense> getTodayExpenses() {

        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null) {
            return new ArrayList<>();
        }

        return expenseDAO.getExpensesByDate(cycle.getId(), LocalDate.now());
    }


    public int getUserId() {
        return currentUserId;
    }

    public boolean isLoggedIn() {
        return currentUserId != NO_USER_ID;
    }

    public String getCurrentUserName() {
        if (!isLoggedIn()) {
            return null;
        }
        User user = userDAO.getUserById(currentUserId);
        return user == null ? null : user.getUsername();
    }

    public int getCategoryIdByName(String name) {
        Cycle cycle = cycleDAO.getCycleByUser(currentUserId);
        if (cycle == null || name == null) {
            return -1;
        }

        List<Category> categories = categoryDAO.getAllCategories(cycle.getId());
        for (Category category : categories) {
            if (category.getName().equals(name)) {
                return category.getId();
            }
        }

        return -1;
    }

    public String getCategoryNameById(int id) {
        Category category = categoryDAO.getCategoryById(id);
        return category == null ? null : category.getName();
    }
}

package com.example.masroofy;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.sql.Statement;

public class DataBaseManager {
    public static Connection getConnection() {
        try {
            String url = "jdbc:sqlite:identifier.sqlite";
            return DriverManager.getConnection(url);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
    public void initDB() {
        String createUsers = """
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL
        );""";

        String createAuth = """
        CREATE TABLE IF NOT EXISTS auth (
                user_id INTEGER PRIMARY KEY,
                pin_hash TEXT NOT NULL,
                FOREIGN KEY (user_id) REFERENCES users(id)
        );""";

        String createCycles = """
        CREATE TABLE IF NOT EXISTS cycles (
             id INTEGER PRIMARY KEY AUTOINCREMENT,
             user_id INTEGER NOT NULL,
             total_budget REAL NOT NULL,
             start_date DATE NOT NULL,
             end_date DATE NOT NULL,

             FOREIGN KEY (user_id) REFERENCES users(id)
        );""";

        String createExpenses = """
        CREATE TABLE IF NOT EXISTS expenses (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            cycle_id INTEGER NOT NULL,
            category_id INTEGER NOT NULL,
            amount REAL NOT NULL,
            type TEXT NOT NULL, -- EXPENSE / INCOME
            date DATETIME NOT NULL,

             FOREIGN KEY (cycle_id) REFERENCES cycles(id),
             FOREIGN KEY (category_id) REFERENCES categories(id)
        );""";

        String createCategories = """
        CREATE TABLE IF NOT EXISTS categories (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            cycle_id INTEGER NOT NULL,
            name TEXT NOT NULL,

            FOREIGN KEY (cycle_id) REFERENCES cycles(id)
        );""";

        String unique= """
                CREATE UNIQUE INDEX IF NOT EXISTS idx_category_unique ON categories(cycle_id, name);
        """;

        try (Connection conn = getConnection()) {
            if (conn == null) {
                throw new SQLException("Failed to open SQLite connection");
            }

            try (Statement stmt = conn.createStatement()) {
                stmt.execute("PRAGMA foreign_keys = ON");
                stmt.execute(createUsers);
                stmt.execute(createAuth);
                stmt.execute(createCycles);
                stmt.execute(createCategories);
                stmt.execute(createExpenses);
                stmt.execute(unique);
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}

package com.example.masroofy;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.sql.Statement;
import java.sql.ResultSet;

public class DataBaseManager {
    public static Connection getConnection() {
        try {
            String url = "jdbc:sqlite:identifier.sqlite";
            return DriverManager.getConnection(url);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
    public void initDB() {
        String createUsers = """
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL
        );""";

        String createAuth = """
        CREATE TABLE IF NOT EXISTS auth (
                user_id INTEGER PRIMARY KEY,
                pin_hash TEXT NOT NULL,
                FOREIGN KEY (user_id) REFERENCES users(id)
        );""";

        String createCycles = """
        CREATE TABLE IF NOT EXISTS cycles (
             id INTEGER PRIMARY KEY AUTOINCREMENT,
             user_id INTEGER NOT NULL,
             total_budget REAL NOT NULL,
             start_date DATE NOT NULL,
             end_date DATE NOT NULL,
             
             FOREIGN KEY (user_id) REFERENCES users(id)
        );""";

        String createExpenses = """
        CREATE TABLE IF NOT EXISTS expenses (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            cycle_id INTEGER NOT NULL,
            category_id INTEGER NOT NULL,
            amount REAL NOT NULL,
            type TEXT NOT NULL, -- EXPENSE / INCOME
            date DATETIME NOT NULL,

             FOREIGN KEY (cycle_id) REFERENCES cycles(id),
             FOREIGN KEY (category_id) REFERENCES categories(id)
        );""";

        String createCategories = """
        CREATE TABLE IF NOT EXISTS categories (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            cycle_id INTEGER NOT NULL,
            name TEXT NOT NULL,
            
            FOREIGN KEY (cycle_id) REFERENCES cycles(id)
        );""";

        String unique= """
                CREATE UNIQUE INDEX IF NOT EXISTS idx_category_unique ON categories(cycle_id, name);
        """;

        try (Connection conn = getConnection()) {
            if (conn == null) {
                throw new SQLException("Failed to open SQLite connection");
            }

            try (Statement stmt = conn.createStatement()) {
                stmt.execute("PRAGMA foreign_keys = ON");
                stmt.execute(createUsers);
                ensureUsernameColumn(stmt);
                stmt.execute(createAuth);
                stmt.execute(createCycles);
                stmt.execute(createCategories);
                stmt.execute(createExpenses);
                stmt.execute(unique);
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }

    private void ensureUsernameColumn(Statement stmt) throws SQLException {
        boolean hasUsername = false;
        boolean hasName = false;

        try (ResultSet rs = stmt.executeQuery("PRAGMA table_info(users)")) {
            while (rs.next()) {
                String column = rs.getString("name");
                if ("username".equalsIgnoreCase(column)) {
                    hasUsername = true;
                } else if ("name".equalsIgnoreCase(column)) {
                    hasName = true;
                }
            }
        }

        if (!hasUsername) {
            stmt.execute("ALTER TABLE users ADD COLUMN username TEXT");
            if (hasName) {
                stmt.execute("UPDATE users SET username = name WHERE username IS NULL");
            }
        }
    }
}
